create extension if not exists pgcrypto;
create table public.tracked_deals (id uuid primary key default gen_random_uuid(),user_id uuid null,listing_provider text not null,listing_id text not null,listing_url text null,status text not null check(status in('discovered','watching','purchased','repairing','listed_for_sale','sold','abandoned','failed')),first_seen_at timestamptz not null,last_seen_at timestamptz not null,created_at timestamptz not null default now(),updated_at timestamptz not null default now());
create unique index tracked_deals_owner_listing_uidx on public.tracked_deals(coalesce(user_id,'00000000-0000-0000-0000-000000000000'::uuid),listing_provider,listing_id);create index tracked_deals_user_idx on public.tracked_deals(user_id);create index tracked_deals_status_idx on public.tracked_deals(status);create index tracked_deals_created_idx on public.tracked_deals(created_at desc);
create table public.deal_prediction_snapshots(id uuid primary key default gen_random_uuid(),deal_id uuid not null references public.tracked_deals(id) on delete cascade,captured_at timestamptz not null,payload jsonb not null,created_at timestamptz not null default now());create index prediction_snapshots_deal_idx on public.deal_prediction_snapshots(deal_id,captured_at);create index prediction_snapshots_created_idx on public.deal_prediction_snapshots(created_at desc);
create table public.deal_actual_outcomes(deal_id uuid primary key references public.tracked_deals(id) on delete cascade,payload jsonb not null,created_at timestamptz not null default now(),updated_at timestamptz not null default now());
create table public.actual_parts(id uuid primary key default gen_random_uuid(),deal_id uuid not null references public.tracked_deals(id) on delete cascade,payload jsonb not null,created_at timestamptz not null default now());create index actual_parts_deal_idx on public.actual_parts(deal_id);create index actual_parts_created_idx on public.actual_parts(created_at desc);
create table public.deal_events(id uuid primary key default gen_random_uuid(),deal_id uuid not null references public.tracked_deals(id) on delete cascade,type text not null check(type in('discovered','analysis_completed','watch_started','purchased','diagnosis_confirmed','part_ordered','part_received','repair_started','repair_completed','listed','sold','abandoned')),occurred_at timestamptz not null,metadata jsonb not null default '{}'::jsonb,created_at timestamptz not null default now());create index deal_events_deal_idx on public.deal_events(deal_id,occurred_at);create index deal_events_created_idx on public.deal_events(created_at desc);
create function public.prevent_prediction_snapshot_mutation() returns trigger language plpgsql as $$ begin raise exception 'deal_prediction_snapshots are append-only'; end $$;create trigger prediction_snapshots_no_update before update or delete on public.deal_prediction_snapshots for each row execute function public.prevent_prediction_snapshot_mutation();
alter table public.tracked_deals enable row level security;alter table public.deal_prediction_snapshots enable row level security;alter table public.deal_actual_outcomes enable row level security;alter table public.actual_parts enable row level security;alter table public.deal_events enable row level security;
comment on table public.deal_prediction_snapshots is 'Immutable typed Repair Deals intelligence snapshots stored as JSONB. No public RLS policy until authentication is implemented.';
